css:
#header-html,
#footer-html,
.print-heading,
.print-format .page-header,
.print-format .page-footer,
.page-header,
.page-footer,
#page-header,
#page-footer {
  display: none !important;
}

.print-format {
  font-family: "Inter", "Helvetica", Arial, sans-serif;
  color: #1f2937;
  font-size: 11px;
  padding: 0 !important;
  margin: 0;
}

@page {
  margin: 10mm;
}

.print-format * {
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.report-meta {
  display: flex;
  justify-content: space-between;
  font-size: 10px;
  color: #64748b;
  margin-bottom: 6px;
}

.report-header {
  text-align: center;
  border-bottom: 2px solid #1f2937;
  padding-bottom: 8px;
  margin-bottom: 12px;
}

.brand-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 10px;
  color: #1f2937;
  margin-bottom: 4px;
}

.brand-logo {
  height: 14px;
  width: auto;
}

.brand-text {
  font-weight: 600;
}

.report-title {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 0.4px;
  text-transform: uppercase;
}

.report-subtitle {
  font-size: 10px;
  color: #64748b;
  margin-top: 2px;
}

.section-title {
  font-weight: 600;
  font-size: 11px;
  margin: 12px 0 6px;
  padding-bottom: 4px;
  border-bottom: 1px solid #e2e8f0;
}

.section-body {
  font-size: 11px;
  color: #334155;
  padding: 2px 0 6px;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.info-grid.two-columns {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-top: 8px;
}

.info-card {
  border: 1px solid #cbd5f5;
  border-radius: 4px;
  padding: 8px;
}

.info-card table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.info-card td {
  padding: 2px 0;
  vertical-align: top;
  line-height: 1.4;
}

.info-card .label {
  width: 42%;
  color: #64748b;
  white-space: nowrap;
}

.info-card .value {
  text-align: left;
  font-weight: 600;
  color: #111827;
  word-break: break-word;
}

.inspection-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.inspection-card {
  border: 1px solid #cbd5f5;
  border-radius: 4px;
  padding: 8px;
}

.inspection-title {
  font-weight: 600;
  margin-bottom: 6px;
  color: #0f172a;
}

.inspection-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.inspection-list li {
  padding: 2px 0;
}

.inspection-item {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}

.inspection-note {
  font-size: 10px;
  color: #64748b;
  padding-left: 2px;
}

.status {
  font-weight: 600;
}

.status.ok {
  color: #059669;
}

.status.need-attention {
  color: #d97706;
}

.status.replace {
  color: #dc2626;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-top: 8px;
}

.parts-list {
  margin: 0;
  padding-left: 16px;
  color: #334155;
}

.signature-page {
  page-break-before: always;
  margin-top: 16px;
}

.signature-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
  margin-top: 12px;
}

.signature-title {
  font-weight: 600;
  color: #1f2937;
  margin-bottom: 24px;
}

.signature-line {
  border-bottom: 1px solid #94a3b8;
  margin-bottom: 8px;
}

.signature-fields {
  font-size: 10px;
  color: #64748b;
  display: grid;
  gap: 4px;
}

.signature-label {
  color: #475569;
}

.signature-footer {
  text-align: center;
  font-size: 10px;
  color: #64748b;
  border-top: 1px solid #e2e8f0;
  padding-top: 8px;
  margin-top: 16px;
}

#header-html, #footer-html, .print-heading,
.print-format .page-header, .print-format .page-footer { display: none !important; }

.wo-print {
  font-family: "Inter", "Helvetica", Arial, sans-serif;
  color: #1a1a1a; font-size: 9px; margin: 0; padding: 0 !important;
}
@page { margin: 8mm; }
.wo-print * { -webkit-print-color-adjust: exact; print-color-adjust: exact; }

.wo-header {
  background: #1f2937; color: #fff; padding: 14px 18px;
  display: flex; justify-content: space-between; align-items: flex-start;
}
.wo-brand { font-size: 18px; font-weight: 800; letter-spacing: 1px; }
.wo-tagline { font-size: 9px; color: #cbd5e1; margin-top: 2px; }
.wo-header-right { text-align: right; font-size: 8px; color: #cbd5e1; font-family: monospace; }

.wo-title-bar {
  background: #d4a017; color: #1f2937; padding: 6px 18px;
  display: flex; justify-content: space-between; align-items: center;
  font-weight: 800;
}
.wo-title-text { font-size: 11px; letter-spacing: 1px; }
.wo-title-no { font-size: 10px; font-family: monospace; }

.wo-info-box {
  display: grid; grid-template-columns: 1fr 1fr;
  border: 1px solid #d1d5db; margin: 10px 0 8px;
}
.wo-info-col { padding: 8px 12px; }
.wo-info-col:first-child { border-right: 1px solid #d1d5db; }
.wo-info-heading {
  font-size: 8px; font-weight: 700; letter-spacing: 1.5px;
  color: #6b7280; margin-bottom: 4px;
}
.wo-info-tbl { width: 100%; border-collapse: collapse; }
.wo-info-tbl td { padding: 1.5px 0; font-size: 9px; vertical-align: top; }
.wo-lbl { width: 30%; color: #6b7280; font-family: monospace; font-size: 8px; }
.wo-val { font-weight: 600; }

.wo-section-title {
  font-size: 8px; font-weight: 700; letter-spacing: 1.5px; color: #1f2937;
  margin: 10px 0 4px; border-bottom: 1px solid #d1d5db; padding-bottom: 3px;
}

.wo-items { width: 100%; border-collapse: collapse; }
.wo-items thead th {
  background: #1f2937; color: #fff; padding: 4px 6px;
  font-size: 8px; font-weight: 600; letter-spacing: 0.5px; text-transform: uppercase;
}
.wo-items tbody td { padding: 4px 6px; border-bottom: 1px solid #e5e7eb; vertical-align: top; font-size: 9px; }
.wo-items tbody tr:nth-child(even) { background: #f9fafb; }

.ci-no { width: 24px; text-align: center; font-weight: 600; }
.ci-name { font-weight: 600; }
.ci-detail { font-family: monospace; font-size: 8px; color: #6b7280; margin-top: 1px; }
.ci-qty { width: 30px; text-align: center; }
.ci-rate { width: 100px; text-align: right; white-space: nowrap; }
.ci-amt { width: 110px; text-align: right; font-weight: 600; white-space: nowrap; }
.wo-items thead .ci-qty, .wo-items thead .ci-rate, .wo-items thead .ci-amt { text-align: center; }

.wo-totals { display: flex; justify-content: flex-end; margin-top: 4px; }
.wo-totals-tbl { width: 240px; border-collapse: collapse; }
.wo-totals-tbl td { padding: 2px 0; font-size: 9px; }
.wt-lbl { text-align: left; color: #6b7280; font-style: italic; }
.wt-val { text-align: right; font-weight: 600; }
.wt-grand td { border-top: none; padding: 0; }
.wt-grand .wt-lbl, .wt-grand .wt-val {
  background: #d4a017; color: #1f2937;
  font-weight: 800; font-size: 11px; font-style: normal;
  padding: 6px 10px; margin-top: 4px;
}
.wt-grand .wt-lbl { text-align: left; }
.wt-grand .wt-val { text-align: right; }

.wo-terms {
  border: 1px solid #d1d5db; padding: 6px 10px; margin-bottom: 8px;
}
.wo-terms ul { margin: 0; padding-left: 14px; }
.wo-terms li { font-size: 8px; color: #4b5563; margin-bottom: 2px; }

.wo-sig-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 16px;
  border: 1px solid #d1d5db; padding: 10px 14px; margin-top: 8px;
}
.wo-sig-title { font-size: 8px; font-weight: 700; letter-spacing: 1px; color: #1f2937; }
.wo-sig-space { height: 36px; }
.wo-sig-line { border-bottom: 1px solid #1a1a1a; width: 70%; margin-bottom: 3px; }
.wo-sig-name { font-size: 9px; font-weight: 600; }

.wo-footer {
  background: #1f2937; color: #cbd5e1; padding: 5px 18px;
  font-size: 7px; text-align: center; letter-spacing: 0.5px; margin-top: 10px;
}

#header-html,
#footer-html,
.print-heading,
.print-format .page-header,
.print-format .page-footer,
.page-header,
.page-footer,
#page-header,
#page-footer {
  display: none !important;
}

.print-format.invoice-format {
  font-family: "Inter", "Helvetica", Arial, sans-serif;
  color: #0f172a;
  font-size: 11px;
  padding: 0 !important;
  margin: 0 auto;
  max-width: 180mm;
}

@page {
  margin: 12mm;
}

.print-format * {
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

.header-title {
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 2px;
}

.header-subtitle {
  font-size: 10px;
  color: #475569;
  margin-bottom: 10px;
}

.meta-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1.4fr;
  gap: 12px;
  align-items: start;
  font-size: 10px;
}

.meta-block {
  line-height: 1.6;
}

.label {
  color: #64748b;
}

.value {
  font-weight: 600;
  color: #111827;
}

.divider {
  border-bottom: 2px solid #1f2937;
  margin: 12px 0 14px;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 16px;
}

.info-card {
  border: 1px solid #cbd5e1;
  border-radius: 8px;
  padding: 12px 14px;
}

.card-title {
  font-size: 10px;
  font-weight: 700;
  margin-bottom: 8px;
  letter-spacing: 0.4px;
}

.card-line {
  display: flex;
  gap: 8px;
  align-items: center;
  font-size: 11px;
}

.card-line .label {
  min-width: 64px;
}

.card-line .plate {
  display: inline-block;
  background: #111827;
  color: #ffffff;
  padding: 4px 10px;
  border-radius: 6px;
  font-weight: 700;
  letter-spacing: 1px;
}

.section-title {
  font-weight: 700;
  font-size: 11px;
  margin-bottom: 8px;
  color: #111827;
}

.items-table {
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 18px;
}

.items-table th,
.items-table td {
  border: 1px solid #cbd5e1;
  padding: 8px 10px;
  vertical-align: top;
}

.items-table th {
  background: #e2e8f0;
  font-size: 10px;
  text-align: left;
}

.items-table td {
  font-size: 10px;
}

.items-table .text-right {
  text-align: right;
}

.items-table .text-center {
  text-align: center;
}

.items-table .bold {
  font-weight: 700;
}

.items-table .col-code {
  width: 16%;
}

.items-table .col-qty {
  width: 8%;
}

.items-table .col-price,
.items-table .col-total {
  width: 14%;
}

.summary-grid {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 16px;
  align-items: end;
}

.cashier-block {
  text-align: center;
  color: #1f2937;
  font-size: 11px;
}

.cashier-line {
  border-bottom: 1px solid #cbd5e1;
  margin: 30px auto 0;
  width: 70%;
}

.totals {
  font-size: 11px;
}

.total-row {
  display: flex;
  justify-content: space-between;
  padding: 4px 0;
  color: #1f2937;
}

.grand-total {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: #f1f5f9;
  border-radius: 6px;
  padding: 10px 14px;
  margin-top: 8px;
  border: 1px solid #cbd5e1;
}

.grand-label {
  font-weight: 700;
  font-size: 12px;
}

.grand-value {
  font-weight: 700;
  font-size: 14px;
}

#header-html, #footer-html, .print-heading,
.print-format .page-header, .print-format .page-footer { display: none !important; }

.spr-print {
  font-family: "Inter", "Helvetica", Arial, sans-serif;
  color: #1a1a1a; font-size: 9px; margin: 0; padding: 0 !important;
  display: flex; flex-direction: column;
  min-height: calc(100vh - 16mm);
}
@page { margin: 8mm; }
.spr-print * { -webkit-print-color-adjust: exact; print-color-adjust: exact; }

.spr-content { flex: 1; }
.spr-bottom { margin-top: auto; }

.spr-header {
  background: #1f2937; color: #fff; padding: 14px 18px;
  display: flex; justify-content: space-between; align-items: flex-start;
}
.spr-brand { font-size: 18px; font-weight: 800; letter-spacing: 1px; }
.spr-tagline { font-size: 9px; color: #cbd5e1; margin-top: 2px; }
.spr-header-right { text-align: right; font-size: 8px; color: #cbd5e1; font-family: monospace; }

.spr-title-bar {
  background: #d4a017; color: #1f2937; padding: 6px 18px;
  display: flex; justify-content: space-between; align-items: center;
  font-weight: 800;
}
.spr-title-text { font-size: 10px; letter-spacing: 1px; }
.spr-title-no { font-size: 10px; font-family: monospace; }

.spr-info-box {
  display: grid; grid-template-columns: repeat(4, 1fr);
  border: 1px solid #d1d5db; margin: 10px 0 8px; padding: 8px 12px; gap: 8px;
}
.spr-info-label { font-size: 7px; font-weight: 700; letter-spacing: 1px; color: #6b7280; }
.spr-info-value { font-size: 9px; font-weight: 600; margin-top: 2px; }

.spr-section-title {
  font-size: 8px; font-weight: 700; letter-spacing: 1.5px; color: #1f2937;
  margin: 10px 0 4px; border-bottom: 1px solid #d1d5db; padding-bottom: 3px;
}

.spr-items { width: 100%; border-collapse: collapse; }
.spr-items thead th {
  background: #1f2937; color: #fff; padding: 4px 6px;
  font-size: 8px; font-weight: 600; letter-spacing: 0.5px;
}
.spr-items tbody td { padding: 4px 6px; border-bottom: 1px solid #e5e7eb; font-size: 9px; }
.spr-items tbody tr:nth-child(even) { background: #f9fafb; }

.si-no { width: 24px; text-align: center; font-weight: 600; }
.si-code { width: 90px; font-family: monospace; font-size: 8px; }
.si-qty { width: 36px; text-align: center; font-weight: 600; }
.si-uom { width: 36px; text-align: center; }
.si-status { width: 70px; text-align: center; }

.status-prepared {
  background: #d1fae5; color: #065f46; padding: 2px 6px; border-radius: 8px;
  font-size: 7px; font-weight: 700; text-transform: uppercase;
}
.status-rejected {
  background: #fee2e2; color: #991b1b; padding: 2px 6px; border-radius: 8px;
  font-size: 7px; font-weight: 700; text-transform: uppercase;
}
.status-oos {
  background: #fef3c7; color: #92400e; padding: 2px 6px; border-radius: 8px;
  font-size: 7px; font-weight: 700; text-transform: uppercase;
}
.status-pending {
  background: #e5e7eb; color: #374151; padding: 2px 6px; border-radius: 8px;
  font-size: 7px; font-weight: 700; text-transform: uppercase;
}

.spr-remarks {
  border: 1px solid #d1d5db; padding: 6px 10px; font-size: 9px; color: #4b5563;
}

.spr-sig-grid {
  display: grid; grid-template-columns: 1fr 1fr; gap: 16px;
  border: 1px solid #d1d5db; padding: 10px 14px;
}
.spr-sig-title { font-size: 8px; font-weight: 700; letter-spacing: 1px; color: #1f2937; }
.spr-sig-space { height: 36px; }
.spr-sig-line { border-bottom: 1px solid #1a1a1a; width: 70%; margin-bottom: 3px; }
.spr-sig-name { font-size: 9px; font-weight: 600; }

.spr-footer {
  background: #1f2937; color: #cbd5e1; padding: 5px 18px;
  font-size: 7px; text-align: center; letter-spacing: 0.5px; margin-top: 10px;
}

#header-html,
#footer-html,
.print-heading,
.print-format .page-header,
.print-format .page-footer,
.page-header,
.page-footer,
#page-header,
#page-footer {
  display: none !important;
}

.print-format.vh-format {
  font-family: "Inter", "Helvetica", Arial, sans-serif;
  color: #0f172a;
  font-size: 11px;
  margin: 0;
  padding: 0 !important;
}

@page {
  margin: 0mm;
}

.print-format * {
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}

/* Table, not flexbox - wkhtmltopdf's flex support is unreliable enough
   that light text on a dark background can render black in the actual PDF
   export even though it looks fine in an HTML/Chromium preview. Tables are
   the reliable layout primitive for wkhtmltopdf (see Nota Service's CSS
   for the same fix applied there). */
.vh-header {
  background: #161b33;
  color: #fff !important;
  padding: 28px 32px 20px;
  border-collapse: collapse;
}

.vh-header-left {
  vertical-align: top;
  text-align: left;
}

.vh-company {
  font-size: 26px;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: #f0c419 !important;
}

.vh-tagline {
  font-size: 11px;
  letter-spacing: 0.12em;
  color: #94a3b8 !important;
  margin-top: 4px;
}

.vh-header-contact {
  vertical-align: top;
  text-align: right;
  font-size: 10px;
  color: #cbd5e1 !important;
  line-height: 1.6;
}

.vh-title-bar {
  background: #f0c419;
  color: #161b33;
  padding: 16px 32px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.vh-title {
  font-size: 20px;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: 0.02em;
}

.vh-title-right {
  text-align: right;
}

.vh-doc-no {
  font-size: 13px;
  font-weight: 700;
}

.vh-doc-date {
  font-size: 10px;
  color: #4b3d06;
  margin-top: 2px;
}

/* Table, not flexbox - same reasoning as .vh-header above. */
.vh-plate-box {
  margin: 24px 0 0;
  width: calc(100% - 64px);
  margin-left: 32px;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  border-collapse: separate;
}

.vh-plate-left {
  vertical-align: top;
  text-align: left;
  padding: 20px 24px;
  width: 60%;
}

.vh-plate-right {
  vertical-align: top;
  text-align: left;
  padding: 20px 24px;
  border-left: 1px solid #eef1f5;
}

.vh-plate-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: #94a3b8;
  margin-bottom: 6px;
}

.vh-plate-number {
  font-size: 30px;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #0f172a;
  font-family: "Courier New", monospace;
}

.vh-plate-desc {
  font-size: 12px;
  color: #475569;
  margin-top: 4px;
}

.vh-owner-name {
  font-size: 16px;
  font-weight: 700;
  color: #0f172a;
}

.vh-owner-phone {
  font-size: 12px;
  color: #475569;
  margin-top: 2px;
}

.vh-info-table {
  width: calc(100% - 64px);
  margin: 20px 32px 0;
  border-collapse: collapse;
}

.vh-info-table tr {
  border-bottom: 1px solid #eef1f5;
}

.vh-info-label {
  padding: 9px 4px;
  font-size: 10.5px;
  color: #94a3b8;
  width: 160px;
  vertical-align: top;
}

.vh-info-value {
  padding: 9px 4px;
  font-size: 12px;
  color: #0f172a;
  font-weight: 600;
  vertical-align: top;
}

.vh-notice {
  margin: 20px 32px 0;
  background: #fdf6e3;
  border: 1px solid #f0e0a8;
  border-left: 3px solid #f0c419;
  border-radius: 6px;
  padding: 14px 18px;
  font-size: 11px;
  color: #52432a;
  line-height: 1.7;
}

.vh-signatures {
  margin-top: 28px;
  width: calc(100% - 64px);
  margin-left: 32px;
  margin-right: 32px;
  border-collapse: collapse;
}

.vh-sig {
  vertical-align: top;
  text-align: left;
  width: 50%;
  padding: 0 12px 24px 0;
}

.vh-sig-title {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: #94a3b8;
  margin-bottom: 40px;
}

.vh-sig-line {
  border-bottom: 1px solid #94a3b8;
  margin-bottom: 6px;
}

.vh-sig-name {
  font-size: 11px;
  color: #475569;
}

.vh-footer {
  margin-top: 12px;
  background: #161b33;
  color: #94a3b8 !important;
